#include <print>
#include <stack>
#include <queue>

int main() {
    std::stack<int> in;
    std::stack<int> out;
    in.push(1);
    in.push(2);
    in.push(3);

    if (out.empty()) {
        while (!in.empty()) {
            out.push(in.top());
            in.pop();
        }
    }
    std::println("出队 {}", out.top());
    out.pop();

    in.push(4);
    std::println("补进 4 之后，out 顶上还是 {}", out.top());

    std::queue<int> a;
    std::queue<int> b;
    a.push(1);
    a.push(2);
    a.push(3);
    while (a.size() > 1) {
        b.push(a.front());
        a.pop();
    }
    std::println("栈顶是 {}", a.front());
    a.pop();
    while (!b.empty()) {
        a.push(b.front());
        b.pop();
    }
    return 0;
}

